<script setup>
import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue'
import { modules, stages, academyLabs, lessonCount, preparation, terms, ownerOfLesson, modulePrerequisites } from './curriculum.js'
import { cases } from './cases.js'
import { state, hydrate, exportData, importData, storageStatus } from './store.js'
import Sandbox from './Sandbox.vue'
import MiniSystem from './MiniSystem.vue'
import HomeDemo from './HomeDemo.vue'
import EvidenceLens from './EvidenceLens.vue'
import PlainText from './PlainText.vue'
import InvestigationDesk from './InvestigationDesk.vue'
import PracticeGuide from './PracticeGuide.vue'
import EncodingSample from './EncodingSample.vue'
import SsrfSample from './SsrfSample.vue'
import GuidedLesson from './GuidedLesson.vue'
import {topicTeaching} from './teaching.js'
const props=defineProps({initialRoute:{type:String,default:'/'}})
const route=ref(props.initialRoute), ready=ref(false),search=ref(''),stageFilter=ref('all'),mode=ref('experiment'),probe=ref('control'),step=ref(0),prediction=ref(null),boundary=ref(null),caseAnswer=ref(null),caseRevealed=ref(false),difficulty=ref('all'),labModule=ref('all'),hideSolved=ref(false),savedOnly=ref(false),labPage=ref(0),labOpen=ref(''),hintLevel=ref(0),toast=ref(''),mysteryId=ref('access-control'),themeOpen=ref(false),help=ref(false),experimentView=ref('guided')
const guidedObservation=ref(null),freeObservation=ref(null),lessonTools=ref(false)
const currentExperiment=computed(()=>experimentView.value==='guided'?guidedObservation.value:freeObservation.value)
let toastTimer
const parts=computed(()=>route.value.split('/').filter(Boolean))
const view=computed(()=>parts.value[0]||'home')
const module=computed(()=>modules.find(m=>m.id===parts.value[1])||modules[0])
const lessonIndex=computed(()=>Math.min(Math.max(Number.parseInt(parts.value[2])||0,0),module.value.lessons.length-1))
const lesson=computed(()=>module.value.lessons[lessonIndex.value])
const doneCount=computed(()=>Object.keys(state.done).length)
const solvedCount=computed(()=>Object.values(state.labs).filter(Boolean).length)
const percent=computed(()=>Math.round(doneCount.value/lessonCount*100))
const next=computed(()=>{if(state.last){const m=modules.find(m=>m.lessons.some(l=>l.id===state.last));const i=m?.lessons.findIndex(l=>l.id===state.last);if(m&&!state.done[state.last])return {m,i}}for(const m of modules){const i=m.lessons.findIndex(l=>!state.done[l.id]);if(i>=0)return {m,i}}return {m:modules[0],i:0}})
const filteredModules=computed(()=>modules.filter(m=>(stageFilter.value==='all'||m.stage===stageFilter.value)&&`${m.title} ${m.lessons.map(l=>l.title).join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
const filteredLabs=computed(()=>academyLabs.filter(l=>(labModule.value==='all'||l.module===labModule.value)&&(difficulty.value==='all'||l.difficulty===difficulty.value)&&(!hideSolved.value||!state.labs[l.id])&&(!savedOnly.value||state.saved[l.id])&&l.title.toLowerCase().includes(search.value.toLowerCase())))
const labPageSize=12
const labPageCount=computed(()=>Math.max(1,Math.ceil(filteredLabs.value.length/labPageSize)))
const visibleLabs=computed(()=>filteredLabs.value.slice(labPage.value*labPageSize,(labPage.value+1)*labPageSize))
watch([search,labModule,difficulty,hideSolved,savedOnly],()=>labPage.value=0)
watch(labPageCount,()=>labPage.value=Math.min(labPage.value,labPageCount.value-1))
async function turnLabPage(offset){labPage.value=Math.min(Math.max(labPage.value+offset,0),labPageCount.value-1);await nextTick();document.querySelector('.lab-options')?.scrollIntoView({block:'start'})}
const due=computed(()=>modules.filter(m=>state.passed[m.id]&&(!state.reviews[m.id]||Date.now()-state.reviews[m.id]>3*86400000)))
const currentCase=computed(()=>cases[view.value==='mystery'?mysteryId.value:module.value.id])
function shuffled(correct,wrong,key){const options=[{text:correct,correct:true},...wrong.map(text=>({text,correct:false}))];const offset=[...key].reduce((a,c)=>a+c.charCodeAt(0),0)%3;return options.slice(offset).concat(options.slice(0,offset))}
const predictions=computed(()=>shuffled(lesson.value.evidence,[lesson.value.limit,cases[module.value.id].wrong[0]],lesson.value.id))
const boundaries=computed(()=>shuffled(lesson.value.mechanism,cases[module.value.id].wrong,lesson.value.id+'boundary'))
const caseChoices=computed(()=>currentCase.value?shuffled(currentCase.value.correct,currentCase.value.wrong,currentCase.value.id+'case'):[])
const canComplete=computed(()=>state.explored[lesson.value.id]&&prediction.value!==null&&predictions.value[prediction.value]?.correct&&boundary.value!==null&&boundaries.value[boundary.value]?.correct)
const selectedLab=computed(()=>academyLabs.find(l=>l.id===labOpen.value))
const activeStage=computed(()=>stages.find(s=>s.id===module.value.stage))
const noteKey=computed(()=>view.value==='labs'&&selectedLab.value?selectedLab.value.id:module.value.id)
const casePassed=computed(()=>caseAnswer.value!==null&&caseChoices.value[caseAnswer.value]?.correct)
async function tabKey(event){const buttons=[...event.currentTarget.querySelectorAll('[role=tab]')];const at=buttons.indexOf(event.target);if(at<0)return;const offset=event.key==='ArrowRight'?1:event.key==='ArrowLeft'?-1:0;if(!offset&&event.key!=='Home'&&event.key!=='End')return;event.preventDefault();const index=event.key==='Home'?0:event.key==='End'?buttons.length-1:(at+offset+buttons.length)%buttons.length;buttons[index].click();await nextTick();buttons[index].focus()}
function link(id,i=0){return `#/learn/${id}/${i}`}
function go(path){window.location.hash='#'+path}
function say(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500)}
function readRoute(){const raw=window.location.hash.slice(1);route.value=raw.startsWith('/')?raw:'/';if(view.value==='learn'&&!modules.some(m=>m.id===parts.value[1])){route.value='/path';say('That lesson does not exist. Choose a module below.')} }
function newMystery(){const choices=modules.filter(m=>!['foundations','encoding','investigation','essential-skills','fieldcraft'].includes(m.id));const prev=mysteryId.value;const pool=choices.filter(m=>m.id!==prev);mysteryId.value=pool[Math.floor(Math.random()*pool.length)].id;caseAnswer.value=null;caseRevealed.value=false}
function skipToWorkspace(){const main=document.querySelector('main');main?.focus({preventScroll:true});main?.scrollIntoView({block:'start'})}
async function openLessonCheck(){mode.value='check';lessonTools.value=true;await nextTick();document.querySelector('.mode-tabs [aria-selected=true]')?.focus()}
function complete(){if(!canComplete.value)return;state.done[lesson.value.id]=true;say('Evidence check passed. Try the next variation.');if(lessonIndex.value<module.value.lessons.length-1)go(`/learn/${module.value.id}/${lessonIndex.value+1}`);else mode.value='transfer'}
function passCase(){if(!casePassed.value||view.value==='mystery')return;state.passed[module.value.id]=true;state.reviews[module.value.id]=Date.now();say('Transfer check passed. Your review is due in 3 days.')}
function openLab(lab){labOpen.value=labOpen.value===lab.id?'':lab.id;hintLevel.value=0}
async function restore(event){try{await importData(event.target.files?.[0]);say('Backup merged. Existing learning records were kept.')}catch(e){say(e.message)}event.target.value=''}
function applyTheme(){document.documentElement.dataset.atmosphere=state.palette;document.documentElement.classList.toggle('dark',state.dark);document.documentElement.style.colorScheme=state.dark?'dark':'light'}
watch(()=>[state.palette,state.dark],()=>{if(ready.value)applyTheme()})
watch(route,()=>{lessonTools.value=false;guidedObservation.value=null;freeObservation.value=null;mode.value='experiment';experimentView.value='guided';probe.value='control';step.value=0;prediction.value=null;boundary.value=null;caseAnswer.value=null;caseRevealed.value=false;search.value='';themeOpen.value=false;toast.value='';clearTimeout(toastTimer);if(view.value==='learn')state.last=lesson.value.id;if(ready.value){window.scrollTo({top:0});document.title=(view.value==='sample'?(parts.value[1]==='ssrf'?'SSRF · Learning sample':'Encoding from zero · Learning sample'):view.value==='learn'?module.value.title:view.value==='labs'?'Practice':view.value==='path'?'Learning path':'Learn to investigate')+' · Websec Decompiled';setTimeout(()=>{document.querySelector('main')?.focus({preventScroll:true});const rail=document.querySelector('.lesson-rail');const active=rail?.querySelector('[aria-current=step]');if(rail&&active&&rail.scrollWidth>rail.clientWidth)rail.scrollLeft+=active.getBoundingClientRect().left-rail.getBoundingClientRect().left-(rail.clientWidth-active.clientWidth)/2},0)}})
onMounted(()=>{hydrate();ready.value=true;const raw=window.location.hash;if(!raw.startsWith('#/')){const slug=window.location.pathname.split('/').filter(Boolean).filter(p=>p!=='websec-decompiled'&&p!=='index.html')[0];if(slug&&modules.some(m=>m.id===slug))window.history.replaceState(null,'',link(slug));else if(slug==='glossary')window.history.replaceState(null,'','#/reference')}readRoute();applyTheme();newMystery();window.addEventListener('hashchange',readRoute)})
onUnmounted(()=>{window.removeEventListener('hashchange',readRoute);clearTimeout(toastTimer)})
</script>

<template>
<div class="academy workshop">
<button class="skip" type="button" aria-controls="workspace" @click="skipToWorkspace">Skip to learning workspace</button>
<header v-if="view!=='sample'" class="topbar">
 <a class="brand" href="#/" aria-label="Websec Decompiled home"><span class="brand-mark">w<span>:</span></span><span>websec<span class="brand-sub">decompiled</span></span></a>
 <nav aria-label="Main navigation"><a href="#/path" :aria-current="view==='path'||view==='learn'?'page':undefined">Learn</a><a href="#/labs" :aria-current="view==='labs'?'page':undefined">Practice</a><a href="#/mystery" :aria-current="view==='mystery'?'page':undefined">Investigate</a><a href="#/reference" :aria-current="view==='reference'?'page':undefined">Reference</a></nav>
 <div class="header-tools"><a class="progress-link" href="#/progress" :aria-label="`${doneCount} of ${lessonCount} lessons checked`"><span class="tiny-progress" :style="{'--progress':percent+'%'}"></span><span>{{percent}}%</span></a><div class="theme-wrap"><button class="icon-button" aria-label="Appearance settings" :aria-expanded="themeOpen" @click="themeOpen=!themeOpen">◐</button><div v-if="themeOpen" class="theme-panel"><strong>Your atmosphere</strong><button v-for="(name,id) in {ocean:'Ocean slate',sage:'Matcha forest',indigo:'Velvet indigo',espresso:'Warm espresso'}" :key="id" :aria-pressed="state.palette===id" @click="state.palette=id"><i :class="id"></i>{{name}}<span v-if="state.palette===id">✓</span></button><button @click="state.dark=!state.dark">{{state.dark?'☀ Switch to light':'☾ Switch to dark'}}</button></div></div></div>
</header>
<div v-if="storageStatus.error" class="storage-warning" role="status">{{storageStatus.error}} <button @click="exportData">Export now</button></div>
<main id="workspace" :class="{'learning-workspace':view==='learn','sample-workspace':view==='sample'}" tabindex="-1">
<SsrfSample v-if="view==='sample'&&parts[1]==='ssrf'" />
<EncodingSample v-else-if="view==='sample'&&parts[1]==='encoding'" />
<template v-else-if="view==='home'">
 <section class="welcome-home">
  <div class="welcome-copy"><span class="eyebrow">YOUR WEB SECURITY WORKSHOP</span><h1>Understand it.<br>Change it.<br><em>See why it works.</em></h1><p>Learn with small fictional websites, ready-to-click inputs, and explanations beside the result. One useful question at a time.</p><a class="button primary" :href="link(next.m.id,next.i)">{{state.last||doneCount?'Continue my learning':'Start learning from the beginning'}} <span>→</span></a><small>{{next.m.title}} · {{next.m.lessons[next.i].title}}</small></div>
  <div class="welcome-preview"><div class="welcome-preview-top"><span>YOUR LEARNING ROUTINE</span><span aria-hidden="true">↗</span></div><ol><li><b>1</b><div><strong>Know what you’re trying to find.</strong><p>A plain explanation, a named setting, and a clear question.</p></div></li><li><b>2</b><div><strong>Make a small change.</strong><p>Choose an example. See the input, the decision, and the response.</p></div></li><li><b>3</b><div><strong>Explain it, then try another setting.</strong><p>Understand the cause before moving to an unfamiliar challenge.</p></div></li></ol><a href="#/sample/ssrf" class="welcome-sample"><span>Try the SSRF request workbench</span><strong>Change a URL. Inspect what the server requests. →</strong></a></div>
 </section>
 <div class="workshop-overview"><span><strong>{{modules.length}}</strong> topics</span><span><strong>{{lessonCount}}</strong> guided examples</span><span><strong>{{academyLabs.length}}</strong> linked practice labs</span><a href="#/progress">Progress saved in this browser ↗</a></div>
 <section class="section-block workshop-choices"><div class="section-heading"><div><span class="eyebrow">CHOOSE YOUR NEXT STEP</span><h2>A little guidance. Room to explore.</h2></div></div><div class="workshop-choice-grid"><a href="#/path"><span>01 / LEARN</span><h3>Build the foundations</h3><p>Follow the ordered path or find a specific topic. Every lesson begins with a question.</p><strong>Open learning path →</strong></a><a href="#/mystery"><span>02 / INVESTIGATE</span><h3>Choose your own next move</h3><p>Use a fictional workspace without a vulnerability label. Keep evidence and test your reasoning.</p><strong>Try an investigation →</strong></a><a href="#/labs"><span>03 / PRACTISE</span><h3>Take it to a real challenge</h3><p>Review each lab’s related skills and record your own attempts. You solve the challenge.</p><strong>Browse practice labs →</strong></a></div></section>
 <details class="home-playground"><summary>Just curious? Try a product request without leaving this page.</summary><HomeDemo /></details>

</template>

<template v-else-if="view==='path'">
 <div class="page-intro"><div class="eyebrow">THE LEARNING PATH</div><h1>From requests to reasoning.</h1><p>Start with web requests, then build one skill at a time. Open a stage to see its topics. You can revisit any lesson or search for a missing skill.</p></div>
 <div class="filter-row"><label class="search-box"><span>⌕</span><input v-model="search" type="search" placeholder="Find a topic or skill…" aria-label="Find a topic or skill"></label><label class="select-label">Stage<select v-model="stageFilter"><option value="all">Every stage</option><option v-for="s in stages" :key="s.id" :value="s.id">{{s.number}} · {{s.title}}</option></select></label></div>
 <details v-for="s in stages.filter(s=>filteredModules.some(m=>m.stage===s.id))" :key="s.id" class="path-stage" :open="s.id===stages[0].id||Boolean(search)||stageFilter!=='all'"><summary class="path-stage-heading"><span class="large-number">{{s.number}}</span><div><h2>{{s.title}}</h2><p>{{s.description}}</p></div><span class="stage-expand">Open stage +</span></summary><div class="module-list"><div v-for="m in filteredModules.filter(m=>m.stage===s.id)" :key="m.id" class="module-row"><a :href="link(m.id)"><span class="module-symbol">{{state.passed[m.id]?'✓':'↗'}}</span><span><strong>{{m.title}}</strong><small>{{topicTeaching[m.id].headline}}</small><small>{{m.lessons.length}} lessons · {{m.lessons.filter(l=>state.done[l.id]).length}} checked <span v-if="state.passed[m.id]">· transfer check passed</span></small></span><span class="row-arrow">→</span></a><details><summary>See the skills you’ll build</summary><ol><li v-for="(l,i) in m.lessons" :key="l.id"><a :href="link(m.id,i)">{{l.title}} <span v-if="state.done[l.id]">✓</span></a></li></ol></details></div></div></details>
 <div v-if="!filteredModules.length" class="empty-state"><h2>No matching skills yet.</h2><p>Try “cookies”, “blind”, “tokens”, or a broader topic.</p><button class="button" @click="search='';stageFilter='all'">Clear filters</button></div>
</template>

<template v-else-if="view==='learn'">
 <div class="lesson-breadcrumb"><a href="#/path">Learning path</a><span>/</span><span>{{activeStage.number}} · {{activeStage.title}}</span></div>
 <div class="lesson-heading"><div><div class="eyebrow">{{module.lessons.length}} LESSONS · {{module.lessons.filter(l=>state.done[l.id]).length}} CHECKED</div><h1>{{module.title}}</h1></div></div>
 <details class="lesson-tools" :open="lessonTools" @toggle="lessonTools=$event.target.open"><summary><span>Lesson {{lessonIndex+1}} / {{module.lessons.length}} · {{lesson.title}}</span><span>Lesson tools +</span></summary>
 <div class="lesson-switcher"><label for="lesson-select">Lesson <select id="lesson-select" :value="lessonIndex" @change="go('/learn/'+module.id+'/'+$event.target.value)"><option v-for="(l,i) in module.lessons" :key="l.id" :value="i">{{state.done[l.id]?'✓ ':''}}{{i+1}}. {{l.title}}</option></select></label><span>{{lessonIndex+1}} / {{module.lessons.length}}</span><a :href="link(module.id,Math.max(0,lessonIndex-1))" aria-label="Previous experiment" :aria-disabled="lessonIndex===0">←</a><a :href="lessonIndex<module.lessons.length-1?link(module.id,lessonIndex+1):'#/path'" aria-label="Next experiment">→</a></div>
 <div class="mode-tabs" role="tablist" aria-label="Lesson modes" @keydown="tabKey"><button v-for="(name,id) in {experiment:'Learn',trace:'Inspect',check:'Check',transfer:'Apply'}" :key="id" role="tab" :id="'lesson-tab-'+id" :aria-controls="'lesson-panel-'+id" :aria-selected="mode===id" :tabindex="mode===id?0:-1" @click="mode=id">{{name}}</button></div>
<div class="lesson-experience-switch"><span>{{experimentView==='guided'?'Guided lesson · no typing needed':'Free exploration · choose your own inputs'}}</span><button class="quiet-button" @click="experimentView=experimentView==='guided'?'model':'guided'">{{experimentView==='guided'?'Explore freely ↗':'Back to guided lesson ←'}}</button></div> <a v-if="module.id==='ssrf'" class="encoding-sample-invite" href="#/sample/ssrf"><span>NEW LEARNING SAMPLE</span><strong>Inspect an image importer’s HTTP exchange</strong><span>Edit the URL, inspect the outgoing GET, and read the returned body. →</span></a>
 <a v-if="module.id==='encoding'" class="encoding-sample-invite" href="#/sample/encoding"><span>NEW LEARNING SAMPLE</span><strong>Start encoding from zero</strong><span>A guided visual lesson, one small idea at a time. →</span></a>
 <aside v-if="help" class="analogy"><span>THINK OF IT THIS WAY</span><p><PlainText :text="module.analogy" /></p></aside>
<button class="quiet-button" @click="help=!help" :aria-expanded="help">{{help?'Close analogy':'Everyday analogy'}} ↗</button></details>
 <div class="lesson-layout"><div class="lesson-body">
 <section v-show="mode==='experiment'" class="experiment-panel" id="lesson-panel-experiment" role="tabpanel" aria-labelledby="lesson-tab-experiment"><GuidedLesson v-show="experimentView==='guided'" :module="module" :lesson-index="lessonIndex" @observed="guidedObservation=$event" @explored="state.explored[lesson.id]=true" @continue="openLessonCheck" @explore="experimentView='model'"/><MiniSystem v-show="experimentView==='model'" :module-id="module.id" :lesson-index="lessonIndex" :mechanism="lesson.mechanism" :limit="lesson.limit" :active="mode==='experiment'&&experimentView==='model'" @observed="freeObservation=$event" @explored="state.explored[lesson.id]=true" @continue="openLessonCheck" /><details v-if="experimentView==='model'" class="investigation-brief"><summary>The idea behind this investigation</summary><p><PlainText :text="lesson.change" /></p><p><strong>Keep in mind:</strong> <PlainText :text="lesson.limit" /></p><div v-if="modulePrerequisites[module.id]?.length" class="prereq-links"><span>Helpful foundations:</span><a v-for="id in modulePrerequisites[module.id]" :key="id" :href="link(id)">{{modules.find(m=>m.id===id).title}}</a></div></details></section>
 <section v-show="mode==='trace'" class="trace-panel" id="lesson-panel-trace" role="tabpanel" aria-labelledby="lesson-tab-trace"><EvidenceLens v-if="currentExperiment?.snapshot" :context="lesson.id" :snapshot="currentExperiment.snapshot" :baseline="currentExperiment.baseline" :history="currentExperiment.history" :fields="currentExperiment.fields"/><div v-else class="trace-start"><h3>Trace your own request.</h3><p>Try an example in the app first. Its actual model checkpoints will appear here.</p><button class="button primary" @click="mode='experiment'">Open the experiment →</button></div><details class="concept-story"><summary>The four-step idea behind this lesson</summary><div class="trace-nodes" aria-label="Trace steps"><button v-for="(name,i) in ['Input','Interpretation','Evidence','Limits']" :key="name" :aria-pressed="step===i" @click="step=i"><span>{{i+1}}</span>{{name}}</button></div><div class="trace-card"><span class="eyebrow">STEP {{step+1}} OF 4</span><h3>{{['What you control','Where meaning changes','What you can observe','What this does not prove'][step]}}</h3><p><PlainText :text="[lesson.change,lesson.mechanism,lesson.evidence,lesson.limit][step]" /></p><div class="trace-controls"><button class="quiet-button" :disabled="step===0" @click="step--">← Previous</button><button class="button" @click="step<3?step++:mode='check'">{{step<3?'Next step':'Try the evidence check'}} →</button></div></div></details><PracticeGuide :module-id="module.id" /></section>
 <section v-show="mode==='check'" class="check-panel" id="lesson-panel-check" role="tabpanel" aria-labelledby="lesson-tab-check"><div v-if="!state.explored[lesson.id]" class="exercise-needed">First, run the two examples in the guided lesson. Then use their evidence to answer these questions.<button class="quiet-button" @click="mode='experiment';experimentView='guided'">Open the experiment →</button></div><div class="eyebrow">EXPLAIN THE OBSERVATION</div><h3>Which result fits this change?</h3><p><PlainText :text="lesson.change" /></p><div class="choice-list"><button v-for="(answer,i) in predictions" :key="answer.text" :class="{chosen:prediction===i,correct:prediction===i&&answer.correct,incorrect:prediction===i&&!answer.correct}" @click="prediction=i"><span>{{String.fromCharCode(65+i)}}</span>{{answer.text}}</button></div><p v-if="prediction!==null" role="status" class="feedback">{{predictions[prediction].correct?'Yes. Now explain the boundary below.':'Look for the direct observation predicted by this change. A general limitation or an untested inference is not that observation.'}}</p><template v-if="prediction!==null&&predictions[prediction].correct"><h3>Why does that result make sense?</h3><div class="choice-list"><button v-for="(answer,i) in boundaries" :key="answer.text" :class="{chosen:boundary===i,correct:boundary===i&&answer.correct,incorrect:boundary===i&&!answer.correct}" @click="boundary=i"><span>{{String.fromCharCode(65+i)}}</span>{{answer.text}}</button></div><p v-if="boundary!==null" class="feedback" role="status">{{boundaries[boundary].correct?'You connected the evidence to its mechanism. Try the transfer case to test a different setting.':'The explanation must identify a server or browser mechanism and match the evidence. Revisit the trace and try again.'}}</p></template><button class="button primary" :disabled="!canComplete" @click="complete">{{state.done[lesson.id]?'Check again & continue':'Save check & continue'}} →</button><p class="fine-print">Complete the guided comparison, then connect the evidence to its mechanism before saving. A concept check is separate from solving a lab.</p></section>
 <section v-show="mode==='transfer'" class="transfer-panel" id="lesson-panel-transfer" role="tabpanel" aria-labelledby="lesson-tab-transfer"><div class="eyebrow">A DIFFERENT SETTING · MODULE TRANSFER CHECK</div><h3>Choose your next useful test.</h3><p class="case-scene">{{currentCase.scene}}</p><p><strong>{{currentCase.question}}</strong></p><div class="choice-list"><button v-for="(answer,i) in caseChoices" :key="answer.text" :class="{chosen:caseAnswer===i,correct:caseAnswer===i&&answer.correct,incorrect:caseAnswer===i&&!answer.correct}" @click="caseAnswer=i"><span>{{String.fromCharCode(65+i)}}</span>{{answer.text}}</button></div><p v-if="caseAnswer!==null" class="feedback" role="status">{{casePassed?currentCase.why:'That choice leaves the important boundary untested. Think about what one controlled request would actually establish.'}}</p><button class="button primary" :disabled="!casePassed" @click="passCase">Save transfer check ✓</button><a class="quiet-link" href="#/labs" @click="labModule=module.id">Find related practice →</a></section>
 <details class="lesson-notes"><summary>Keep a note or a question</summary><label :for="'note-'+module.id">What surprised you? What would you test next?</label><textarea :id="'note-'+module.id" v-model="state.notes[module.id]" maxlength="20000" rows="4" placeholder="A clue, a failed assumption, a question to revisit…"></textarea><small>Saved in this browser. Include notes in your progress export.</small></details>
 <a class="lesson-source quiet-link" :href="module.source" target="_blank" rel="noopener noreferrer">Read the primary technical reference ↗</a><div class="lesson-bottom"><a v-if="lessonIndex>0" :href="link(module.id,lessonIndex-1)">← Previous lesson</a><span v-else></span><a v-if="lessonIndex<module.lessons.length-1" :href="link(module.id,lessonIndex+1)">Next lesson →</a><a v-else href="#/path">Back to the learning path →</a></div>
 </div></div>
</template>

<template v-else-if="view==='labs'">
 <div class="page-intro"><div class="eyebrow">PRACTICE WITH A PLAN</div><h1>Bring your understanding<br>to a live target.</h1><p>Choose a challenge, inspect its related skills, and keep a record of your evidence. These {{academyLabs.length}} links are your saved Academy catalogue, not a claim to include every newly released lab.</p></div>
 <div class="filter-row"><label class="search-box"><span>⌕</span><input v-model="search" type="search" placeholder="Find a practice challenge…" aria-label="Search practice challenges"></label><label class="select-label">Topic<select v-model="labModule"><option value="all">Every topic</option><option v-for="m in modules.filter(m=>academyLabs.some(l=>l.module===m.id))" :value="m.id" :key="m.id">{{m.title}}</option></select></label><label class="select-label">Difficulty<select v-model="difficulty"><option value="all">All levels</option><option>Apprentice</option><option>Practitioner</option><option>Expert</option></select></label></div><div class="lab-options"><span>{{filteredLabs.length}} challenges</span><label><input type="checkbox" v-model="hideSolved"> Hide solved</label><label><input type="checkbox" v-model="savedOnly"> Saved only</label></div>
 <div class="lab-list"><article v-for="lab in visibleLabs" :key="lab.id" :data-lab-id="lab.id" class="lab-card" :class="{expanded:labOpen===lab.id}"><div class="lab-card-top"><div><span class="difficulty" :class="lab.difficulty.toLowerCase()">{{lab.difficulty}}</span><span class="lab-topic">{{modules.find(m=>m.id===lab.module).title}}</span></div><button class="icon-button" :aria-label="`${state.saved[lab.id]?'Unsave':'Save'} ${lab.title}`" :aria-pressed="!!state.saved[lab.id]" @click="state.saved[lab.id]=!state.saved[lab.id]">{{state.saved[lab.id]?'★':'☆'}}</button></div><button class="lab-title-button" :aria-expanded="labOpen===lab.id" @click="openLab(lab)"><h2>{{lab.title}}</h2><span>{{labOpen===lab.id?'−':'+'}}</span></button><div class="lab-readiness"><span class="readiness-track" aria-hidden="true"><i v-for="skill in preparation(lab)" :key="skill.id" :class="{checked:state.done[skill.id]}"></i></span><span class="status-dot" :class="{pending:preparation(lab).some(l=>!state.done[l.id])}"></span>{{preparation(lab).filter(l=>state.done[l.id]).length}} / {{preparation(lab).length}} related concept checks <span v-if="state.labs[lab.id]" class="solved-label">✓ Marked solved</span></div>
 <div v-if="labOpen===lab.id" class="lab-detail"><h3>Review the underlying skills</h3><p class="muted">Review these explicitly mapped concept skills before you begin. The challenge may combine them in an unfamiliar way; the links explain mechanisms without revealing its solution.</p><a v-for="l in preparation(lab)" :key="l.id" class="preparation-link" :class="{prepared:state.done[l.id]}" :href="link(ownerOfLesson(l.id).id,ownerOfLesson(l.id).lessons.indexOf(l))"><span>{{state.done[l.id]?'✓':'○'}}</span><span>{{l.title}}<small v-if="ownerOfLesson(l.id).id!==lab.module"> · {{ownerOfLesson(l.id).title}}</small></span><span>↗</span></a><a class="quiet-link" :href="link(lab.module)">Browse the entire module →</a><div class="lab-actions"><a class="button primary" :href="lab.url" target="_blank" rel="noopener noreferrer">Open Academy lab ↗</a><label class="solved-check"><input type="checkbox" v-model="state.labs[lab.id]"> I solved this lab</label></div><details class="practice-assist"><summary>Stuck? Return to the evidence.</summary><p>These prompts support your investigation without revealing this lab’s solution.</p><ol><li>Capture a working baseline. Identify the user, endpoint, input type, and state.</li><li v-if="hintLevel>=1">{{preparation(lab).at(-1).transfer}}</li><li v-if="hintLevel>=2">{{preparation(lab).at(-1).limit}} Test one assumption and compare the complete response with your baseline.</li></ol><button v-if="hintLevel<2" class="button" @click="hintLevel++">Reveal next investigation prompt</button><p v-else>For the challenge’s official hints and full solution, use its Academy page. Afterwards, write why the technique worked and which variation would break it.</p></details><label :for="lab.id+'-notes'">Your evidence & failed assumptions</label><textarea :id="lab.id+'-notes'" v-model="state.notes[lab.id]" maxlength="20000" rows="4" placeholder="Baseline → mutation → evidence → what this proves"></textarea></div></article></div>
 <nav v-if="filteredLabs.length" class="lab-pagination" aria-label="Practice pages"><span>Showing {{labPage*labPageSize+1}}–{{Math.min((labPage+1)*labPageSize,filteredLabs.length)}} of {{filteredLabs.length}}</span><div><button class="button" :disabled="labPage===0" @click="turnLabPage(-1)">← Previous</button><span>{{labPage+1}} / {{labPageCount}}</span><button class="button" :disabled="labPage===labPageCount-1" @click="turnLabPage(1)">Next →</button></div></nav><div v-if="!filteredLabs.length" class="empty-state"><h2>No challenges match these filters.</h2><button class="button" @click="search='';labModule='all';difficulty='all';hideSolved=false;savedOnly=false">Reset filters</button></div>
</template>

<template v-else-if="view==='mystery'">
 <div class="page-intro"><div class="eyebrow">INVESTIGATE WITHOUT THE LABEL</div><h1>Let the evidence<br>choose the test.</h1><p>CTFs don’t announce the bug. Practise choosing a useful next move before revealing the topic. Use the investigation desk to replay requests in fictional workspaces, or take a quick decision case. Your Academy lab records stay separate.</p></div>
 <div class="mode-tabs" role="tablist" aria-label="Investigation style" @keydown="tabKey"><button id="mystery-tab-desk" aria-controls="mystery-panel-desk" role="tab" :tabindex="mode==='experiment'?0:-1" :aria-selected="mode==='experiment'" @click="mode='experiment'">Investigation desk</button><button id="mystery-tab-quick" aria-controls="mystery-panel-quick" role="tab" :tabindex="mode==='trace'?0:-1" :aria-selected="mode==='trace'" @click="mode='trace'">Quick decisions</button></div><InvestigationDesk v-show="mode==='experiment'" id="mystery-panel-desk" role="tabpanel" aria-labelledby="mystery-tab-desk" /><section v-if="currentCase" v-show="mode==='trace'" class="mystery-panel" id="mystery-panel-quick" role="tabpanel" aria-labelledby="mystery-tab-quick"><div class="panel-topline"><span class="status-dot"></span> UNLABELED CASE <button class="quiet-button" @click="newMystery">Another case ↻</button></div><h2>What would you investigate?</h2><p class="case-scene">{{currentCase.scene}}</p><h3>{{currentCase.question}}</h3><div class="choice-list"><button v-for="(answer,i) in caseChoices" :key="answer.text" :class="{chosen:caseAnswer===i,correct:caseAnswer===i&&answer.correct,incorrect:caseAnswer===i&&!answer.correct}" @click="caseAnswer=i"><span>{{String.fromCharCode(65+i)}}</span>{{answer.text}}</button></div><div v-if="caseAnswer!==null" class="feedback" role="status"><p>{{casePassed?currentCase.why:'That choice does not isolate the relevant boundary. Choose a test with a clear control and a concrete observable result.'}}</p><button class="quiet-button" @click="caseRevealed=true">Reveal the topic & related lessons ↗</button></div><div v-if="caseRevealed" class="revealed-topic"><span class="eyebrow">FOLLOW THIS THREAD</span><h3>{{modules.find(m=>m.id===mysteryId).title}}</h3><a class="button" :href="link(mysteryId)">Revisit the mechanism →</a></div></section>
</template>

<template v-else-if="view==='reference'">
 <div class="page-intro"><div class="eyebrow">KEEP THE TOOLS CLOSE</div><h1>Your field notes.</h1><p>A reusable workflow, plain-English vocabulary, and a small request playground. Come here when an unfamiliar term or a failed test interrupts your investigation.</p></div>
 <div class="mode-tabs" role="tablist" aria-label="Reference sections" @keydown="tabKey"><button v-for="(name,id) in {experiment:'Investigation loop',trace:'Plain-English terms',check:'Request playground'}" :key="id" role="tab" :id="'reference-tab-'+id" :aria-controls="'reference-panel-'+id" :aria-selected="mode===id" :tabindex="mode===id?0:-1" @click="mode=id">{{name}}</button></div>
 <section v-show="mode==='experiment'" class="reference-workflow" id="reference-panel-experiment" role="tabpanel" aria-labelledby="reference-tab-experiment"><div v-for="(item,i) in [['Map the feature','Which input, role, parser, file, network request, or state transition does it involve?'],['Capture a baseline','Replay a working request. Record status, body, cookies, redirects, and ordinary timing noise.'],['Predict a difference','Write one hypothesis and the concrete observation that would confirm or contradict it.'],['Change one variable','Keep identity and state controlled. Trace encoding and compare the complete response.'],['Prove the boundary','Separate reflection from execution, acceptance from persistence, and errors from impact.'],['Connect and retain','Write a minimal reproducible proof, its prerequisites, its limits, and the root-cause fix.']]" :key="i"><span>{{String(i+1).padStart(2,'0')}}</span><div><h3>{{item[0]}}</h3><p>{{item[1]}}</p></div></div><aside class="callout"><h3>Use the right environment</h3><p>Experiment on the provided models, CTF targets, or systems you have permission to test. The browser-only models show selected behavior; they do not run real databases, shells, or network attacks.</p></aside><div class="sources"><h3>Go deeper with primary sources</h3><a href="https://portswigger.net/web-security/all-topics" target="_blank" rel="noopener">Academy topic explanations ↗</a><a href="https://portswigger.net/web-security/all-labs" target="_blank" rel="noopener">Current Academy lab catalogue ↗</a><a href="https://portswigger.net/burp/documentation/desktop/getting-started" target="_blank" rel="noopener">Burp Suite getting started ↗</a><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP" target="_blank" rel="noopener">MDN HTTP reference ↗</a></div></section>
 <section v-show="mode==='trace'" id="reference-panel-trace" role="tabpanel" aria-labelledby="reference-tab-trace"><label class="search-box glossary-search"><span>⌕</span><input v-model="search" type="search" placeholder="Find a word without the jargon…" aria-label="Search plain-English terms"></label><dl class="glossary"><div v-for="[term,definition] in terms.filter(t=>t.join(' ').toLowerCase().includes(search.toLowerCase()))" :key="term"><dt>{{term}}</dt><dd>{{definition}}</dd></div></dl><p v-if="!terms.some(t=>t.join(' ').toLowerCase().includes(search.toLowerCase()))" class="empty-state">No matching term. Try a shorter word or search the learning path.</p></section>
 <Sandbox v-show="mode==='check'" id="reference-panel-check" role="tabpanel" aria-labelledby="reference-tab-check" />
</template>

<template v-else-if="view==='progress'">
 <div class="page-intro"><div class="eyebrow">YOUR LEARNING RECORD</div><h1>Understanding, over points.</h1><p>Keep concept checks, transfer checks, and solved labs separate. Each tells you something different about your progress. You have also recorded {{Object.keys(state.missions).length}} fictional workspace investigations.</p></div><div class="stat-grid"><div><strong>{{doneCount}}<span>/{{lessonCount}}</span></strong><p>Concept checks</p></div><div><strong>{{Object.keys(state.passed).length}}<span>/{{modules.length}}</span></strong><p>Transfer checks</p></div><div><strong>{{solvedCount}}<span>/{{academyLabs.length}}</span></strong><p>Labs marked solved</p></div></div><section class="continue-card"><div><div class="eyebrow">YOUR NEXT STEP</div><h2>{{next.m.title}}</h2><p>{{next.m.lessons[next.i].title}}</p></div><a class="circle-link" :href="link(next.m.id,next.i)" aria-label="Continue learning">↗</a></section><section class="section-block"><div class="section-heading"><div><div class="eyebrow">KEEP IT FRESH</div><h2>Revisit after a little distance.</h2></div></div><p class="muted">Passed transfer checks return here after 3 days. Retry the scenario, then explain a variation in your own notes.</p><div v-if="due.length" class="review-list"><a v-for="m in due" :key="m.id" :href="link(m.id)">{{m.title}} <span>Review →</span></a></div><div v-else class="empty-state compact">No reviews due. Pass a module’s transfer check to schedule one.</div></section><section class="backup-panel"><div><h2>Your progress belongs to you.</h2><p>Saved in this browser, without an account. Export before changing devices. Import merges records and preserves current work.</p></div><div class="backup-actions"><button class="button primary" @click="exportData">Export backup ↓</button><label class="button import-label">Import backup ↑<input type="file" accept="application/json,.json" @change="restore"></label></div></section><section class="section-block"><h2>Notes you’ve kept</h2><template v-for="(text,id) in state.notes" :key="id"><details v-if="text" class="saved-note"><summary>{{modules.find(m=>m.id===id)?.title||academyLabs.find(l=>l.id===id)?.title||(id.startsWith('mission:')?'Investigation · '+id.slice(8):id)}}</summary><p>{{text}}</p></details></template><p v-if="!Object.values(state.notes).some(Boolean)" class="muted">Add observations inside a lesson or practice challenge. They’ll appear here.</p></section>
</template>
<template v-else><div class="empty-state"><h1>That page does not exist.</h1><a class="button primary" href="#/path">Return to the learning path →</a></div></template>
</main>
<footer v-if="view!=='sample'" class="footer"><a class="footer-brand" href="#/">websec <span>decompiled</span></a><p>Learn one idea. See its effect. Try it somewhere new.</p><a href="#/progress">Your progress & backups ↗</a></footer>
<div v-if="toast" class="toast" role="status">{{toast}}</div>
</div>
</template>
